use filmcraft_project::{Project,ItemId};use filmcraft_media::MediaSource;use filmcraft_time::Tick;use serde_json::{Value,json};
fn main(){let fixture:Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();let base=&fixture["cases"][0];let sid=base["sequence"].as_u64().unwrap();let mut cases=vec![];const T:i64=254016000000;
for mode in 0..32{let mut p:Project=serde_json::from_value(base["document"]["project"].clone()).unwrap();let generator=filmcraft_media::Generator::ColorMatte{color:[1.,0.,0.,1.]};let source=filmcraft_media::generators::GeneratorSource::new(generator.clone(),320,200,filmcraft_time::FrameRate::new(24,1),Tick(20*T));if let filmcraft_project::ItemKind::Media(media)=&mut p.item_mut(ItemId(1)).unwrap().kind{media.info=source.info().clone();media.media=filmcraft_project::MediaRef::Generator(generator);}
let q=p.sequence_mut(ItemId(sid)).unwrap();let tr=&mut q.video_tracks[0];tr.enabled=mode%8!=1;
for(i,c)in tr.items.iter_mut().enumerate(){c.start=Tick(i as i64*2*T);c.duration=Tick(2*T);c.source_in=Tick(T);c.speed=if mode&2!=0{1.5}else{1.};c.reverse=mode&4!=0;c.enabled=!(mode&8!=0&&i==0);c.frame_hold=if mode&16!=0{Some(Tick(7*T))}else{None};c.hold_filters=mode%3==0;}
let a=tr.items[0].id;let b=tr.items[1].id;tr.transitions.clear();if mode%4!=0{tr.transitions.push(serde_json::from_value(json!({"id":999,"effect":{"effect":"cross_dissolve","params":{},"enabled":true},"start":T,"duration":2*T,"from":if mode%5==0{None}else{Some(a)},"to":if mode%7==0{None}else{Some(b)},"align":"CenterAtCut","reverse":mode%2!=0})).unwrap());}
let mut upper=tr.clone();upper.id=filmcraft_project::TrackId(333);upper.enabled=mode%3!=0;for c in &mut upper.items{c.id=filmcraft_project::ClipId(c.id.0+10000);}upper.transitions.clear();q.video_tracks.push(upper);
let q=p.sequence_mut(ItemId(sid)).unwrap();for tr in &mut q.video_tracks{for item in &mut tr.items{
let mut motion=filmcraft_project::find_effect("motion").unwrap().instance();motion.enabled=mode%4!=0;
motion.params.get_mut("scale").unwrap().keyframes=vec![filmcraft_project::Keyframe::new(Tick(T),filmcraft_project::ParamValue::Float(50.)),filmcraft_project::Keyframe::new(Tick(3*T),filmcraft_project::ParamValue::Float(120.))];
motion.params.get_mut("rotation").unwrap().value=filmcraft_project::ParamValue::Float(19.25);motion.params.get_mut("scale_width").unwrap().value=filmcraft_project::ParamValue::Float(80.);motion.params.get_mut("uniform_scale").unwrap().value=filmcraft_project::ParamValue::Bool(false);
let mut opacity=filmcraft_project::find_effect("opacity").unwrap().instance();opacity.enabled=mode%5!=0;opacity.params.get_mut("opacity").unwrap().keyframes=vec![filmcraft_project::Keyframe::new(Tick(T),filmcraft_project::ParamValue::Float(-20.)),filmcraft_project::Keyframe::new(Tick(3*T),filmcraft_project::ParamValue::Float(140.))];opacity.params.get_mut("blend").unwrap().value=filmcraft_project::ParamValue::Choice(mode as u32);
item.effects=vec![motion,opacity];item.scale_to_frame=mode%3!=0;
}}
for at in [0,T,2*T,3*T]{let q=p.sequence(ItemId(sid)).unwrap();for item in &q.video_tracks[0].items{let mt=item.effect_time_at(Tick(at));let size=p.source_size(item.item).unwrap();let matrix=filmcraft_render::motion_matrix(q,item,size,mt);let(op,blend)=match item.effect("opacity"){Some(e)if e.enabled=>((e.f64_at("opacity",mt)/100.).clamp(0.,1.)as f32,match e.param("blend").map(|p|&p.value){Some(filmcraft_project::ParamValue::Choice(c))=>filmcraft_render::blend::Blend::from_index(*c),_=>filmcraft_render::blend::Blend::Normal}),_=>(1.,filmcraft_render::blend::Blend::Normal)};
cases.push(json!({"document":{"format":"filmcraft.project","schema_version":12,"project":p},"sequence":sid,"clip":item.id,"mode":mode,"at":at,"matrixBits":([matrix.a,matrix.b,matrix.c,matrix.d,matrix.e,matrix.f].map(f64::to_bits)),"opacityBits":op.to_bits(),"blend":blend.index(),"effects":item.effects,"parameters":mt}));}}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases}));}
